### S1: Implement a case-insensitive username system for a web app.

```python
class UsernamSystem:
    """
    Username system where:
    - Usernames are stored in lowercase internally
    - Display name preserves original casing
    - Lookup is case-insensitive
    """
    def __init__(self):
        self.users = {}   # lowercase_username → {display_name, email, ...}

    def register(self, username, email, password):
        """Register new user — case-insensitive uniqueness"""
        normalized = username.strip().casefold()   # Use casefold for comparison!

        if not normalized:
            return {"success": False, "error": "Username cannot be empty"}

        if not username[0].isalpha():
            return {"success": False, "error": "Username must start with a letter"}

        if normalized in self.users:
            return {"success": False, "error": f"Username '{username}' already taken"}

        self.users[normalized] = {
            "display_name": username.strip(),    # Preserve original casing
            "email":        email.strip().casefold(),
            "password":     password,            # In real app: hash this!
        }
        return {"success": True, "message": f"Welcome, {username}!"}

    def login(self, username, password):
        """Login — case-insensitive username lookup"""
        normalized = username.strip().casefold()
        user = self.users.get(normalized)

        if not user:
            return {"success": False, "error": "User not found"}
        if user["password"] != password:
            return {"success": False, "error": "Wrong password"}

        return {"success": True, "display_name": user["display_name"]}

system = UsernamSystem()
print(system.register("Veerababu74", "v@ex.com", "pass123"))
print(system.register("VEERABABU74", "v2@ex.com", "pass123"))  # Duplicate!
print(system.login("veerababu74", "pass123"))  # Case-insensitive login
print(system.login("VEERABABU74", "pass123"))  # Also works!
```

### S2: Build a text normalization pipeline for NLP preprocessing.

```python
def normalize_text_for_nlp(text):
    """
    Normalize text for NLP processing:
    - Consistent casing
    - Remove extra whitespace
    - Expand common contractions
    - Handle special cases
    """
    # Step 1: Casefold for comparison (not lower() — handles Unicode better)
    text = text.strip().casefold()

    # Step 2: Expand contractions
    contractions = {
        "it's":  "it is",  "don't":  "do not",
        "can't": "cannot", "won't":  "will not",
        "i'm":   "i am",   "they're":"they are",
        "we're": "we are", "you're": "you are",
    }
    for contraction, expanded in contractions.items():
        text = text.replace(contraction, expanded)

    # Step 3: Normalize whitespace
    text = " ".join(text.split())   # Multiple spaces → single space

    return text

samples = [
    "It's GREAT that You're Learning Python!",
    "I can't believe  we're   DOING this!",
    "DON'T you WANT to won't stop?",
]
print("NLP Text Normalization:")
for sample in samples:
    normalized = normalize_text_for_nlp(sample)
    print(f"\n  Original:   '{sample}'")
    print(f"  Normalized: '{normalized}'")
```

