# S3: Product name standardization for search indexing
def standardize_for_search(text):
    """Create search-friendly version of product name"""
    return {
        "display":   text.strip().title(),
        "search":    text.strip().casefold(),
        "url_slug":  "-".join(text.strip().lower().split()),
        "initials":  "".join(w[0].upper() for w in text.split() if w),
    }

products = ["DELL INSPIRON LAPTOP", "samsung galaxy s24", "Apple iPad PRO"]
for p in products:
    info = standardize_for_search(p)
    for key, val in info.items():
        print(f"  {key:<10}: {val}")
    print()

# S4: Grade letter normalization
def normalize_grade(grade_input):
    """Normalize various grade formats to standard"""
    g = grade_input.strip().upper()
    grade_map = {
        "EXCELLENT": "A+", "OUTSTANDING": "A+",
        "VERY GOOD": "A",  "GOOD": "B",
        "AVERAGE": "C",    "BELOW AVERAGE": "D",
        "FAIL": "F",       "FAILED": "F"
    }
    return grade_map.get(g, g)   # Return mapped or original

grades = ["excellent", "GOOD", "very good", "A+", "failed", "b"]
for g in grades:
    print(f"  '{g}' → '{normalize_grade(g)}'")

# S5: Case-insensitive command parser
COMMANDS = {
    "help":   lambda: "Available commands: help, quit, list, add",
    "quit":   lambda: "Goodbye!",
    "list":   lambda: "Showing all items...",
    "add":    lambda: "Adding item...",
}

def process_command(user_input):
    cmd = user_input.strip().lower()   # normalize input
    handler = COMMANDS.get(cmd)
    return handler() if handler else f"Unknown command: '{user_input}'. Type 'help'."

for cmd in ["HELP", "List", "  QUIT  ", "delete", "ADD"]:
    print(f"  > {cmd.strip()} → {process_command(cmd)}")
